sqlite3 -json "/data/arabic_dict.db" "SELECT e.id AS entry_id, e.dictionary_id, e.headword, e.headword_norm, e.root, e.root_source, e.pos, e.definitions_text, e.translation_en, e.domain, d.key AS dict_key, d.name_ar AS dict_name_ar, d.source_type, d.period, d.author, d.death_year FROM entries e JOIN dictionaries d ON e.dictionary_id=d.id WHERE e.headword_norm IN ('ارتباط','الارتباط','قرابة','القرابة','صلة','الصلة','مناسبة','المناسبة','تواشج','التواشج','نسبة','النسبة') ORDER BY e.headword_norm, d.source_type, d.death_year ASC NULLS LAST;" 2>/dev/null | python3 -c "
